using Sts2Sim.Core.Commands;
using Sts2Sim.Core.Combat;
using Sts2Sim.Core.Entities.Cards;
using Sts2Sim.Core.Entities.Creatures;
using Sts2Sim.Core.Factories;
using Sts2Sim.Core.Models.Powers;
using Sts2Sim.Core.ValueProps;

namespace Sts2Sim.Core.Models.Cards;

// Token generated by Compact; it is intentionally absent from DefectCardPool's 91 entries.
public sealed class Fuel : CardModel, ICardChoiceBaseValueProvider
{
    private decimal _energy = 1m;
    public CardChoiceBaseValues? CardChoiceBaseValues => new(Energy: (double)_energy);
    public override CardType Type => CardType.Skill;
    public override CardRarity Rarity => CardRarity.Token;
    public override TargetType TargetType => TargetType.Self;
    protected override int CanonicalEnergyCost => 0;
    protected override IReadOnlyCollection<CardKeyword> CanonicalKeywords => [CardKeyword.Exhaust];
    protected override Task OnPlay(CardPlay cardPlay) => PlayerCmd.GainEnergy(_energy, Owner);
    protected override void OnUpgrade() => _energy += 1m;
}
